import ast,copy,hashlib,json
from pathlib import Path
root=Path('/workspace'); runtime=json.load(open(root/'runtime_resolved.json'));p=json.load(open(root/'proposal.json'))
# Validate every keyword used in the supplied study schema with stdlib only.
supported={'"'$schema'"','title','type','additionalProperties','required','properties','minLength','minItems','items','enum','const'}
def validate(value,schema,path='"'$'"'):
 assert not set(schema)-supported,(path,'unsupported schema keys',set(schema)-supported)
 if 'const' in schema:assert value==schema['const'],(path,'const')
 if 'enum' in schema:assert value in schema['enum'],(path,'enum')
 t=schema.get('type')
 if t=='object':
  assert isinstance(value,dict),(path,'object')
  assert not set(schema.get('required',[]))-set(value),(path,'required')
  if schema.get('additionalProperties') is False:assert not set(value)-set(schema['properties']),(path,'additionalProperties')
  for k,v in value.items():
   if k in schema.get('properties',{}):validate(v,schema['properties'][k],path+'.'+k)
 elif t=='array':
  assert isinstance(value,list) and len(value)>=schema.get('minItems',0),(path,'array')
  for i,v in enumerate(value):validate(v,schema['items'],path+'['+str(i)+']')
 elif t=='string':assert isinstance(value,str) and len(value)>=schema.get('minLength',0),(path,'string')
validate(p['study'],runtime['study_schema'])
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(runtime['context']['allowed_observation_ids'])
assert p['parent_trial'] in runtime['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 assert v['role'] in ['candidate','control']
 text=(root/v['file']).read_text(); tree=ast.parse(text);compile(text,v['file'],'exec')
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert config==v['config']
 assert hashlib.sha256(text.encode()).hexdigest() in v['note']
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 init=next(n for n in model.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 args={n.arg for n in init.args.args}
 assert not set(config)-args,(v['file'],'unknown config keys')
 env={'CONFIG':config}
 for arg,default in zip(init.args.args[-len(init.args.defaults):],init.args.defaults):
  if arg.arg in config:
   actual=eval(compile(ast.Expression(default),'<default>','eval'),{'__builtins__':{}},env)
   if isinstance(actual,tuple):actual=list(actual)
   assert actual==config[arg.arg],(v['file'],arg.arg,'CONFIG/default mismatch')
for k in p['knowledge_assessments']:
 assert set(k)=={'knowledge_id','decision','rationale','transformed_mechanism','variant_names','nearest_work_difference','falsifier'}
 assert k['decision'] in ('used','considered','rejected','unresolved')
 assert set(k['variant_names'])<={v['name'] for v in p['variants']}
# Verify every inherited initializer statement survives unchanged and in order.
# Remove only documented new attribute validation/assignment and residual fork.
src=(root/'candidate.py').read_text(); old=(root/'history_g0_r0013_pair_joint_both.py').read_text()
def init_body(s):
 cls=next(n for n in ast.parse(s).body if isinstance(n,ast.ClassDef) and n.name=='Model')
 return next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__').body
b0=init_body(old);b=init_body(src)
i0=next(i for i,n in enumerate(b) if isinstance(n,ast.If) and \"feedback_mode\" in ast.unparse(n.test))
i1=next(i for i,n in enumerate(b) if isinstance(n,ast.Assign) and ast.unparse(n.targets[0])=='self.pair_content_source')
b=b[:i0]+b[i1:]
newfork=next(i for i,n in enumerate(b) if isinstance(n,ast.With) and 'self.feedback_projection' in ast.unparse(n))
b.pop(newfork)
assert ast.dump(ast.Module(body=b,type_ignores=[]))==ast.dump(ast.Module(body=b0,type_ignores=[]))
print('PASS: strict supplied study schema; evidence/protocol/parent references; four variants/roles; config/signature/default/hash consistency; knowledge assessments; exact inherited initialization statements and order.')
print('Proposal SHA256',hashlib.sha256((root/'proposal.json').read_bytes()).hexdigest())
PY"

